// Add type bindings
export interface PowPayload {
  seed_nonce: number;
  nonce: number;
  hash: string;
  difficulty: number;
}

export interface SecurePayload {
  signature: string;
  fingerprint: string;
  client_ip: string;
  pow: PowPayload;
  v: string;
}

// Export wrapper function typed
export function generateSecurePayload(
  username: string,
  timestamp: string,
  nonce_js: string,
  challenge: string,
  client_ip: string,
  difficulty: number
): SecurePayload {
  return generate_secure_payload(username, timestamp, nonce_js, challenge, client_ip, difficulty) as SecurePayload;
}
